// Label every case with its technique: EP, BVA, DT (decision table) or ST (state transition).
const TEST_CASES = [
  {
    id: 'BVA-01',
    technique: 'BVA',
    description: 'startHour boundaries: 6 and 21 rejected, 7 and 20 accepted',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 6, duration: 1 },
        expect: { status: 400, body: { error: 'VALIDATION', field: 'startHour' } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 7, duration: 1 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 20, duration: 1 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 21, duration: 1 },
        expect: { status: 400, body: { error: 'VALIDATION', field: 'startHour' } },
      },
    ],
  },
];

