// LabBook milestone 4 — black-box design of POST /api/bookings, executed.
const TEST_CASES = [
  {
    id: 'BVA-01',
    technique: 'BVA',
    description: 'startHour boundaries: 6 and 21 rejected, 7 and 20 accepted',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 6, duration: 1 },
        expect: { status: 400, body: { error: 'VALIDATION', field: 'startHour' } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 7, duration: 1 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 20, duration: 1 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 21, duration: 1 },
        expect: { status: 400, body: { error: 'VALIDATION', field: 'startHour' } },
      },
    ],
  },
  {
    id: 'BVA-02',
    technique: 'BVA',
    description: 'duration boundaries: 0 and 4 rejected, 1 and 3 accepted',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 0 },
        expect: { status: 400, body: { error: 'VALIDATION', field: 'duration' } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-05', startHour: 9, duration: 3 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-06', startHour: 9, duration: 4 },
        expect: { status: 400, body: { error: 'VALIDATION', field: 'duration' } },
      },
    ],
  },
  {
    id: 'BVA-03',
    technique: 'BVA',
    description: 'booking window: day −1 and day 15 rejected, day 0 (today, 1 h ahead) and day 14 accepted',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-01', startHour: 9, duration: 1 },
        expect: { status: 422, body: { error: 'OUT_OF_WINDOW' } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-02', startHour: 9, duration: 1 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-16', startHour: 9, duration: 1 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-17', startHour: 9, duration: 1 },
        expect: { status: 422, body: { error: 'OUT_OF_WINDOW' } },
      },
    ],
  },
  {
    id: 'BVA-04',
    technique: 'BVA',
    description: 'closing time: ends at 21:00 accepted, ends at 22:00 rejected',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 18, duration: 3 },
        expect: { status: 201 },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 19, duration: 3 },
        expect: { status: 422, body: { error: 'AFTER_CLOSING' } },
      },
    ],
  },
  {
    id: 'DT-01',
    technique: 'DT',
    description: 'outcome rules: lab not found, lab closed, too soon',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB99', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 404, body: { error: 'LAB_NOT_FOUND' } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB03', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 409, body: { error: 'LAB_CLOSED' } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-02', startHour: 8, duration: 1 },
        expect: { status: 422, body: { error: 'TOO_SOON' } },
      },
    ],
  },
  {
    id: 'DT-02',
    technique: 'DT',
    description: 'outcome rules: seat free → CONFIRMED, lab full → PENDING',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-04', startHour: 9, duration: 2 },
        expect: { status: 201, body: { status: 'CONFIRMED' } },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-04', startHour: 9, duration: 2 },
        expect: { status: 201, body: { status: 'PENDING' } },
      },
    ],
  },
  {
    id: 'DT-03',
    technique: 'DT',
    description: 'outcome rules: overlap with own booking, weekly limit',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 3 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-03', startHour: 10, duration: 1 },
        expect: { status: 409, body: { error: 'OVERLAP' } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 3 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-05', startHour: 9, duration: 1 },
        expect: { status: 422, body: { error: 'WEEKLY_LIMIT' } },
      },
    ],
  },
  {
    id: 'ST-01',
    technique: 'ST',
    description: 'CONFIRMED → CANCELLED, then PENDING → CONFIRMED by promotion',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-04', startHour: 9, duration: 2 },
        expect: { status: 201, body: { code: 'BK0001', status: 'CONFIRMED' } },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-04', startHour: 9, duration: 2 },
        expect: { status: 201, body: { code: 'BK0002', status: 'PENDING' } },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 200, body: { status: 'CANCELLED' } } },
      {
        as: 'student2',
        call: 'GET /api/bookings/me',
        expect: { status: 200, body: { '0': { code: 'BK0002', status: 'CONFIRMED' } } },
      },
    ],
  },
  {
    id: 'ST-02',
    technique: 'ST',
    description: 'PENDING → CANCELLED by the student, and CANCELLED → (cancel) rejected',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-04', startHour: 9, duration: 2 },
        expect: { status: 201 },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-04', startHour: 9, duration: 2 },
        expect: { status: 201, body: { code: 'BK0002', status: 'PENDING' } },
      },
      { as: 'student2', call: 'DELETE /api/bookings/BK0002', expect: { status: 200, body: { status: 'CANCELLED' } } },
      {
        as: 'student2',
        call: 'DELETE /api/bookings/BK0002',
        expect: { status: 409, body: { error: 'ALREADY_CANCELLED' } },
      },
    ],
  },
  {
    id: 'ST-03',
    technique: 'ST',
    description: 'CONFIRMED and PENDING → CANCELLED by the lab-closure cascade',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 2 },
        expect: { status: 201, body: { status: 'CONFIRMED' } },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 2 },
        expect: { status: 201, body: { status: 'CONFIRMED' } },
      },
      {
        as: 'student3',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 2 },
        expect: { status: 201, body: { status: 'PENDING' } },
      },
      {
        as: 'manager',
        call: 'PATCH /api/labs/LAB01',
        body: { status: 'CLOSED' },
        expect: { status: 200, body: { cancelled: 3 } },
      },
      { as: 'student3', call: 'GET /api/bookings/me', expect: { status: 200, body: { '0': { status: 'CANCELLED' } } } },
    ],
  },
];

